import asyncio
import ipaddress
import logging

from pysnmp.hlapi.asyncio import (
    CommunityData,
    ContextData,
    ObjectIdentity,
    ObjectType,
    SnmpEngine,
    UdpTransportTarget,
    getCmd,
    setCmd,
)

from taf.hw.optical_switch.exceptions import InvalidHost, OpticalSwitchConnectionError


class SNMPClient:
    def __init__(self, host, timeout, community_read, community_write):
        self._init_verifiers(host, timeout)
        self._host = host
        self._timeout = int(timeout)
        self._community_read = community_read
        self._community_write = community_write
        self._snmp_port = 161
        self._snmp_version = 2 - 1
        self._logger = logging.getLogger(__name__)
        self._logger.setLevel(logging.DEBUG)

    def execute_get_cmd(self, snmp_oid):
        self._logger.debug(f"Executing get command on oid: {snmp_oid}")
        var_binds = asyncio.run(self._execute_cmd(getCmd, ObjectType(ObjectIdentity(snmp_oid))))
        return str(var_binds[0][1])

    def execute_set_cmd(self, snmp_oid, value):
        var_binds = asyncio.run(self._execute_cmd(setCmd, ObjectType(ObjectIdentity(snmp_oid), value)))
        return str(var_binds[0][1])

    async def _execute_cmd(self, cmd_method, object_type):
        community = self._community_read if cmd_method == getCmd else self._community_write
        output = await cmd_method(
            SnmpEngine(),
            CommunityData(community, mpModel=self._snmp_version),
            UdpTransportTarget((self._host, self._snmp_port), timeout=self._timeout),
            ContextData(),
            object_type,
        )
        error_indication, error_status, error_index, var_binds = output
        self._verify_no_error(error_indication, error_status)
        self._logger.debug(f"Returned variable binds: {var_binds}")
        return var_binds

    @staticmethod
    def _verify_no_error(error_indication, error_status):
        if error_status or error_indication:
            error_indication = error_indication or "Unknown connection error occurred!"
            raise OpticalSwitchConnectionError(error_indication)

    def _verify_host(self, host):
        if host is None:
            raise InvalidHost("Host cannot be None")
        if not (self._is_ip(host) or host.startswith("COM") or host.lower().endswith("nsn-rdnet.net")):
            raise InvalidHost(f"Invalid host: {host}")

    @staticmethod
    def _verify_timeout(timeout):
        if not (isinstance(timeout, (int, float))):
            raise TypeError("Timeout must be a number (integer or float)")

    def _init_verifiers(self, host, timeout):
        self._verify_host(host)
        self._verify_timeout(timeout)

    @staticmethod
    def _is_ip(ip_address):
        result = True
        try:
            if isinstance(ip_address, bytes):
                ip_address = ip_address.decode()
            ipaddress.ip_address(ip_address)
        except (ValueError, ipaddress.AddressValueError):
            result = False
        return result
